"""Background music for the demo video, generated by Google's Lyria 3.5 through the Gemini API.

    PYTHONPATH=. python video/make_music.py [--takes 2] [--out video/out]

Writes video/out/music_1.wav, music_2.wav ... (as returned, converted to 48 kHz stereo WAV) and
video/out/music_report.json with each take's length and levels. The call shape is from the music
generation guide: client.interactions.create(model="lyria-3.5", input=PROMPT,
response_format={"type": "audio"}), audio in interaction.output_audio.data (base64).
Instrumental only. Each call has a timeout and one retry; if every call fails no file is written
and video/assemble.py builds the video without music.
"""
from __future__ import annotations

import argparse
import base64
import json
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
from clock import decide, media, models  # noqa: E402
from video import make_voice  # noqa: E402

MODEL = "lyria-3.5"
TIMEOUT_S = 240
PROMPT = """Instrumental only, no vocals, no lyrics. A gentle, soft, unhurried piece for a one-minute film about a person carefully checking a list, step by step.
A felt piano plays a simple warm motif, about one soft note per second, like a quiet clock at 60 BPM. Under it a low, warm pad and a soft upright bass. D major. Calm, attentive, reassuring, a little curious.
No drums, no percussion, no build-up, no climax, no sudden changes. Very steady, quiet volume, so it can sit under on-screen text.
[0:00 - 0:10] Intro: the felt piano alone with the clock-like motif.
[0:10 - 0:45] The pad and the soft bass join. The motif continues with small variations.
[0:45 - 1:10] The piano thins out and the piece resolves gently and ends."""


def one(client, n: int, out: Path) -> dict:
    errors = []
    for attempt in range(2):
        t0 = time.time()
        try:
            res = client.interactions.create(model=MODEL, input=PROMPT, response_format={"type": "audio"}, timeout=TIMEOUT_S)
            audio = getattr(res, "output_audio", None)
            data = getattr(audio, "data", None)
            if not data:
                raise RuntimeError("reply had no audio")
            raw = base64.b64decode(data) if isinstance(data, str) else bytes(data)
            ext = ".wav" if raw[:4] == b"RIFF" else ".mp3"
            tmp = out / f"music_{n}.api{ext}"
            tmp.write_bytes(raw)
            dst = out / f"music_{n}.wav"
            r = media._run(["-y", "-loglevel", "error", "-i", str(tmp), "-ar", "48000", "-ac", "2", "-c:a", "pcm_s16le", str(dst)])
            if r.returncode != 0 or not dst.exists():
                raise RuntimeError("ffmpeg could not read the audio: " + r.stderr[-200:])
            tmp.unlink(missing_ok=True)
            m = make_voice.measure(dst)
            text = getattr(res, "output_text", None)
            return {"file": dst.name, "ok": True, "seconds_to_make": round(time.time() - t0, 1), "attempt": attempt,
                    "duration_s": m["duration_s"], "peak_db": m["peak_db"], "mean_db": m["mean_db"],
                    "notes": (text or "")[:400], "errors": errors}
        except Exception as e:  # noqa: BLE001
            errors.append(models._error_text(e))
    return {"file": f"music_{n}.wav", "ok": False, "errors": errors}


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--takes", type=int, default=2)
    ap.add_argument("--out", default=str(ROOT / "video" / "out"))
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    client = decide.client(TIMEOUT_S * 1000)
    with ThreadPoolExecutor(max_workers=args.takes) as pool:
        rows = list(pool.map(lambda n: one(client, n, out), range(1, args.takes + 1)))
    (out / "music_report.json").write_text(json.dumps({"model": MODEL, "prompt": PROMPT, "takes": rows}, indent=1) + "\n", encoding="ascii", errors="replace")
    for r in rows:
        print(json.dumps(r)[:600])
    return 0 if any(r["ok"] for r in rows) else 1


if __name__ == "__main__":
    sys.exit(main())
